//! M0 slice-1 出口閘(RYOSYS-MVP §5):oracle .il roundtrip 差分,庫級。
//!
//! 每個案例目錄 `corpus/ys-e2e/<case>/` 含:
//! * `case.il` —— 錄製輪階段 A 產出(P-free 層=`read_verilog+hierarchy
//!   -auto-top+proc+opt`;P-bearing 層=去掉 proc;oracle=0.70+179,
//!   vendor-reference/suite-dl,2026-10-27 錄製);
//! * `expected.rtlil` —— 階段 B `read_rtlil case.il; write_rtlil -readable`
//!   產出(=oracle 冪等不動點)。
//!
//! 閘語義:ry-ir 解析 case.il → `write_rtlil_readable` → 歸一化剝首行
//! (§4.2:`# Generated by` 含版本+構建路徑)→ 與 golden 剝首行後
//! **byte-exact**。測試運行零 oracle 依賴。

use std::fs;
use std::path::PathBuf;

fn corpus_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../corpus/ys-e2e")
}

/// §4.2 歸一化:剝首行(前綴 `# Generated by `)。敵意形(第二行起出現
/// 同前綴文字)不剝——只剝第一行。
fn strip_first_line(text: &str) -> &str {
    if text.is_empty() {
        // 拒收形 golden(ys-m2-anchors 的 exit=1 例):0-byte expected.rtlil。
        return "";
    }
    let mut it = text.splitn(2, '\n');
    let first = it.next().unwrap_or("");
    assert!(first.starts_with("# Generated by "), "golden 首行必為 Generated-by: {first:?}");
    it.next().unwrap_or("")
}

#[test]
fn oracle_il_roundtrip_byte_exact() {
    let root = corpus_root();
    let mut cases: Vec<String> = fs::read_dir(&root)
        .expect("corpus/ys-e2e 存在")
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().map(|t| t.is_dir()).unwrap_or(false))
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .filter(|name| {
            let dir = root.join(name);
            // M2 翻轉後:-pb 例與 anchors 4 例(global_ff/posedge_memwr/
            // edge_reject/global_memwr)的 expected.rtlil=proc 後產物或
            // 拒收形 0-byte(非 case.il 的 roundtrip 形),與本測試
            // 「parse case.il→write」不可比——由 ry-difftest 401/406
            // 四件套面承擔;冪等鎖(下測)對這些例仍生效。
            if name.ends_with("-pb")
                || matches!(
                    name.as_str(),
                    "global_ff" | "posedge_memwr" | "edge_reject" | "global_memwr"
                )
            {
                return false;
            }
            dir.join("case.il").exists() && dir.join("expected.rtlil").exists()
        })
        // M1 擴容層的 expected.rtlil 不是 case.il 的 read→write 冪等形:
        // -rj 來自 read_json 流;-hier=hierarchy 變換後(wandwor-hier 的
        // wand/wor 重解析≠case.il;其餘案例恰恆等故 314 時代僥倖通過,
        // 契約面不應依賴該恆等);-sm=simplemap 變換後。三層全部排除,
        // 品質由 ry-difftest 對拍把關(閘語義=M0/P-bearing 冪等層)。
        .filter(|name| {
            !name.ends_with("-rj") && !name.ends_with("-hier") && !name.ends_with("-sm")
        })
        .collect();
    cases.sort();

    // §3-M0 閘①:≥20 例。M2 翻轉後 -pb 層的 expected.rtlil=proc 後產物
    // (已在上方排除),P-bearing 的 roundtrip/冪等鎖由 ry-difftest 的
    // 401/406 四件套面+下方冪等測試(含 -pb 例)承擔。
    assert!(cases.len() >= 20, "roundtrip 案例數 {} < 20", cases.len());

    let mut failures: Vec<String> = Vec::new();
    for case in &cases {
        let dir = root.join(case);
        let il = fs::read_to_string(dir.join("case.il")).unwrap();
        let golden = fs::read_to_string(dir.join("expected.rtlil")).unwrap();

        let design = match ry_ir::parse_rtlil(&il) {
            Ok(d) => d,
            Err(e) => {
                failures.push(format!("{case}: parse 失敗: {e}"));
                continue;
            }
        };
        let out = ry_ir::write_rtlil_readable(&design);
        if strip_first_line(&out) != strip_first_line(&golden) {
            // 找出第一個分歧行,方便定位。
            let mut first_diff = String::new();
            for (a, b) in strip_first_line(&out).lines().zip(strip_first_line(&golden).lines()) {
                if a != b {
                    first_diff = format!("ry={a:?} golden={b:?}");
                    break;
                }
            }
            failures.push(format!("{case}: 輸出分歧(首個分歧行 {first_diff})"));
        }
    }
    assert!(failures.is_empty(), "roundtrip 失敗 {} 例:\n{}", failures.len(), failures.join("\n"));
}

/// 冪等性:read→write 的輸出再走一輪 read→write,必須 byte-exact
/// (oracle §0-2 實測同性質;比 golden 更嚴的第二道鎖)。
#[test]
fn roundtrip_idempotent() {
    let root = corpus_root();
    for entry in fs::read_dir(&root).unwrap() {
        let entry = entry.unwrap();
        if !entry.file_type().unwrap().is_dir() {
            continue;
        }
        let case = entry.file_name().to_string_lossy().into_owned();
        let il = fs::read_to_string(root.join(&case).join("case.il")).unwrap();
        let once = ry_ir::write_rtlil_readable(&ry_ir::parse_rtlil(&il).unwrap());
        let twice = ry_ir::write_rtlil_readable(&ry_ir::parse_rtlil(&once).unwrap());
        assert_eq!(once, twice, "{case}: 二次傾印不冪等");
    }
}
